use once_cell::sync::Lazy;
use std::collections::HashMap;

/// name -> hex, O(1).
///
/// Upstream is `names[color]`, a plain object lookup. The port originally
/// scanned `NAMES` linearly (`.iter().find(...)`), which made per-input cost
/// depend on alphabetical position. See DECISIONS.md D-019.
pub static NAME_MAP: Lazy<HashMap<&'static str, &'static str>> =
    Lazy::new(|| NAMES.iter().copied().collect());

/// hex -> name, O(1), preserving upstream's last-wins collision behaviour.
///
/// `hexNames = flip(names)` assigns in source order, so a later name
/// overwrites an earlier one sharing the same hex (`cyan` beats `aqua`).
/// Inserting in source order reproduces that exactly — see D-004, which this
/// must not regress.
pub static HEX_NAME_MAP: Lazy<HashMap<&'static str, &'static str>> = Lazy::new(|| {
    let mut m = HashMap::with_capacity(HEX_NAMES.len());
    for (hex, name) in HEX_NAMES {
        m.insert(*hex, *name); // later entries overwrite earlier: last-wins
    }
    m
});

#[cfg(test)]
mod map_tests {
    use super::*;

    #[test]
    fn maps_agree_with_linear_scan() {
        // The maps must be indistinguishable from the scans they replace.
        for (k, v) in NAMES {
            assert_eq!(NAME_MAP.get(k), Some(v), "name {k}");
        }
        for (hex, _) in HEX_NAMES {
            let linear = HEX_NAMES
                .iter()
                .filter(|(h, _)| h == hex)
                .next_back()
                .map(|(_, n)| *n);
            assert_eq!(HEX_NAME_MAP.get(hex).copied(), linear, "hex {hex}");
        }
    }

    #[test]
    fn collision_still_resolves_last_wins() {
        assert_eq!(HEX_NAME_MAP.get("0ff").copied(), Some("cyan"));
        assert_eq!(HEX_NAME_MAP.get("f0f").copied(), Some("magenta"));
    }
}
